import java.util.*;

class SortedWalker {
    private Deque<TreeNode> stack = new ArrayDeque<>();

    public SortedWalker(TreeNode root) {
        pushLeft(root);
    }

    // push a node and its whole left spine
    private void pushLeft(TreeNode node) {
        while (node != null) { stack.push(node); node = node.left; }
    }

    public int next() {
        TreeNode node = stack.pop(); // smallest unvisited key
        pushLeft(node.right);        // its successors come from the right subtree
        return node.val;
    }

    public boolean hasNext() {
        return !stack.isEmpty();
    }
}

